#!/usr/bin/env bash
# Download/generate all benchmark datasets into $SEKEJAP_DATA/datasets (default ./data).
# Idempotent (skips anything already present), best-effort per dataset (a failure
# logs and continues). Run inside the orchestrator pod.
set -uo pipefail
D=${SEKEJAP_DATA:-./data}/datasets
mkdir -p "$D"
log(){ echo "[$(date -u +%H:%M:%S)] $*"; }
skip(){ [ -e "$1" ] && { log "skip (exists): $1"; return 0; } || return 1; }

# ── Relational: TPC-H SF1 (generated by duckdb) ──
if ! skip "$D/tpch-sf1/lineitem.csv"; then
  log "TPC-H SF1 (duckdb dbgen)…"
  mkdir -p "$D/tpch-sf1"
  duckdb -c "INSTALL tpch; LOAD tpch; CALL dbgen(sf=1);
             EXPORT DATABASE '$D/tpch-sf1' (FORMAT CSV, DELIMITER '|');" \
    && log "TPC-H SF1 done" || log "TPC-H FAILED"
fi

# ── Relational: ClickBench 10M slice (partial remote parquet — only fetches
#    the row groups needed for LIMIT, not the full 15 GB) ──
if ! skip "$D/clickbench/hits_10m.parquet"; then
  log "ClickBench 10M slice (duckdb httpfs partial read)…"
  mkdir -p "$D/clickbench"
  duckdb -c "INSTALL httpfs; LOAD httpfs;
             COPY (SELECT * FROM read_parquet('https://datasets.clickhouse.com/hits_compatible/hits.parquet') LIMIT 10000000)
             TO '$D/clickbench/hits_10m.parquet' (FORMAT PARQUET);" \
    && log "ClickBench done" || log "ClickBench FAILED"
fi

# ── Spatial: GeoNames allCountries ──
if ! skip "$D/geonames/allCountries.txt"; then
  log "GeoNames allCountries…"
  mkdir -p "$D/geonames"
  curl -sSL https://download.geonames.org/export/dump/allCountries.zip -o "$D/geonames/x.zip" \
    && unzip -o -q "$D/geonames/x.zip" -d "$D/geonames" && rm "$D/geonames/x.zip" \
    && log "GeoNames done" || log "GeoNames FAILED"
fi

# ── Spatial: NYC PostGIS workshop (polygon predicates; best-effort URL) ──
if ! skip "$D/nyc/nyc_neighborhoods.shp"; then
  log "NYC PostGIS workshop…"
  mkdir -p "$D/nyc"
  curl -sSL https://s3.cleverelephant.ca/postgis-workshop-2020.zip -o "$D/nyc/x.zip" \
    && unzip -o -q "$D/nyc/x.zip" -d "$D/nyc" && rm "$D/nyc/x.zip" \
    && log "NYC done" || log "NYC FAILED (needs alternate URL)"
fi

# ── Graph: SNAP com-amazon (real co-purchase graph) ──
if ! skip "$D/snap/com-amazon.ungraph.txt"; then
  log "SNAP com-amazon…"
  mkdir -p "$D/snap"
  curl -sSL https://snap.stanford.edu/data/bigdata/communities/com-amazon.ungraph.txt.gz -o "$D/snap/x.gz" \
    && gunzip -c "$D/snap/x.gz" > "$D/snap/com-amazon.ungraph.txt" && rm "$D/snap/x.gz" \
    && log "SNAP done" || log "SNAP FAILED"
fi

# ── Vector: ann-benchmarks SIFT1M + GloVe-100 (HDF5, ground truth included) ──
mkdir -p "$D/ann"
if ! skip "$D/ann/sift-128-euclidean.hdf5"; then
  log "SIFT1M…"
  curl -sSL http://ann-benchmarks.com/sift-128-euclidean.hdf5 -o "$D/ann/sift-128-euclidean.hdf5" \
    && log "SIFT1M done" || log "SIFT1M FAILED"
fi
if ! skip "$D/ann/glove-100-angular.hdf5"; then
  log "GloVe-100…"
  curl -sSL http://ann-benchmarks.com/glove-100-angular.hdf5 -o "$D/ann/glove-100-angular.hdf5" \
    && log "GloVe-100 done" || log "GloVe-100 FAILED"
fi

# ── Search: BEIR SciFact / NFCorpus / FiQA ──
mkdir -p "$D/beir"
for ds in scifact nfcorpus fiqa; do
  if ! skip "$D/beir/$ds"; then
    log "BEIR $ds…"
    curl -sSL "https://public.ukp.informatik.tu-darmstadt.de/thakur/BEIR/datasets/$ds.zip" -o "$D/beir/$ds.zip" \
      && unzip -o -q "$D/beir/$ds.zip" -d "$D/beir" && rm "$D/beir/$ds.zip" \
      && log "BEIR $ds done" || log "BEIR $ds FAILED"
  fi
done

# ── Special handling (not a simple download) ──
log "LDBC SNB SF1  → generated separately (datagen / pre-gen tarball)."
log "Cohere-1M     → acquired separately (VectorDBBench / HuggingFace)."
log "Yelp dataset  → LICENSE-GATED: place the tar at $D/yelp/ manually."

log "=== dataset sizes ==="
du -sh "$D"/* 2>/dev/null | sort -h
echo "----"
du -sh "$D" 2>/dev/null
log "download-datasets.sh complete"
